KG42.register("clusters-a0d4f0879b5c97759f89b0b0",{"id":"12-p2p_microgrid_trading::v142-d-K002","paper":"12-p2p_microgrid_trading","label":"Delivery deviation accounting and settlement obligations following direct trading","record":{"cluster_id":"v142-d-K002","label":"Delivery deviation accounting and settlement obligations following direct trading","market_meaning":"Uses completed energy exchanges and the differences between committed and actual quantities as inputs to organize the post-trade settlement sequence and deviation charging obligations; the existing chains are not yet sufficient to calculate the amounts payable.","mechanism_ids":["v141-a-M01"],"market_types":["LEM"],"process_stages":["settlement","activation"],"scope_disposition":"compatible","scope_explanation":"Both chains fall within the scope of general P2P trading. The shared execution chain provides only the interface for the trades being settled and does not introduce supplier prices, penalties, or service fees specific to Elecbay.","assembly_status":"partial","boundary_rationale":"This cluster is bounded by the accounting and charging obligations associated with quantity deviations after delivery; these have market meanings distinct from those of trading eligibility and product definitions.","chain_bindings":[{"chain_id":"v141-c-R005","ownership":"primary","role":"core","rationale":"Covers the obligations for post-trade settlement, deviation calculation, and charging."},{"chain_id":"v141-c-R001","ownership":"shared","role":"interface","rationale":"References direct trade execution as the object of settlement; its primary assignment remains in v142-d-K001."}],"connections":[{"connection_id":"v142-d-K002-L001","from_chain_id":"v141-c-R001","to_chain_id":"v141-c-R005","kind":"functional_coupling","from_refs":["v141-c-R001::V::execution.energy_trade","v141-c-R001::phi::v141-c-R001-C002"],"to_refs":["v141-c-R005::phi::v141-c-R005-C001","v141-c-R005::phi::v141-c-R005-C002"],"evidence_ids":["v141-b-g01-ev-03","v141-b-g01-ev-10","v141-b-g01-ev-11"],"rationale":"Direct energy exchange provides the object of settlement, and an obligation to account for deviations arises when commitments and actual delivery differ. The existing precedence relationship remains recorded in R005; this connection does not generate a new scientific dependency edge."}],"object_mappings":[{"mapping_id":"v142-d-K002-O001","kind":"same_node","member_refs":["v141-c-R001::V::execution.energy_trade","v141-c-R005::V::execution.energy_trade"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-ev-02","v141-b-g01-ev-10"],"rationale":"The two occurrences reference the energy exchange function within the same mechanism, respectively in the direct trading description and the settlement sequence; the node references are associated, but the provisions of each chain remain independent."}],"gaps":[{"gap_id":"v142-d-K002-G001","category":"math_incomplete","description":"R005 retains the deviation accounting and charging obligations but provides neither formal objects nor calculation relationships for committed quantities, actual quantities, charging prices, or monetary amounts, preventing closure of quantitative settlement.","chain_ids":["v141-c-R005"],"object_refs":["v141-c-R005::phi::v141-c-R005-C002"],"evidence_ids":["v141-b-g01-ev-11"],"proposal_ids":[],"required_work":"Verify the metering basis and charging method within the scope of the same mechanism; have C supplement quantities and expressions only after obtaining explicit sources, without borrowing pricing provisions from other mechanisms."},{"gap_id":"v142-d-K002-G002","category":"unverified_source","description":"The source entries for direct trading and settlement have not yet been independently audited; this cluster is an experimental candidate.","chain_ids":["v141-c-R001","v141-c-R005"],"object_refs":[],"evidence_ids":["v141-b-g01-ev-02","v141-b-g01-ev-03","v141-b-g01-ev-10","v141-b-g01-ev-11"],"proposal_ids":[],"required_work":"Manually check the original text's scope regarding the trading sequence, deviation trigger conditions, and charging obligations."}]},"rule_refs":["12-p2p_microgrid_trading::v141-c-R005","12-p2p_microgrid_trading::v141-c-R001"],"unresolved_rule_refs":[],"node_ids":["COMP-45aa318377a72aa8","COMP-739917e3869e45a6"]});
